from pathlib import Path
import json,hashlib,sys

campaign=Path.home()/".local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4"
model_task="A2Z-V4-SOL-BUILD-20261007-R4"
mr=campaign/"model_results"/f"{model_task}.json"

if not mr.exists():
    print("E117=R4_RESULT_PENDING",flush=True); raise SystemExit(20)

try:
    env=json.loads(mr.read_text())
except Exception as e:
    print("E117=R4_RESULT_INVALID_JSON",flush=True); raise SystemExit(21)

cp=campaign/env.get("checkpoint","")
if not cp.exists():
    print("E117=R4_CHECKPOINT_MISSING",flush=True); raise SystemExit(22)

required=["TASK.json","WORKER.json","COMPLETE.json","events.jsonl"]
for name in required:
    if not (cp/name).exists():
        print("E117=MISSING_"+name.replace(".","_").upper(),flush=True); raise SystemExit(23)

task=json.loads((cp/"TASK.json").read_text())
worker=json.loads((cp/"WORKER.json").read_text())
complete=json.loads((cp/"COMPLETE.json").read_text())
events=[json.loads(x) for x in (cp/"events.jsonl").read_text().splitlines() if x.strip()]

if task.get("task_id")!=model_task:
    print("E117=TASK_ID_MISMATCH",flush=True); raise SystemExit(30)
if task.get("phase")!="SOL_BUILD" or task.get("model_policy")!="SOL_EXACT":
    print("E117=MODEL_PHASE_OR_POLICY",flush=True); raise SystemExit(31)
if worker.get("model")!="gpt-5.6-sol":
    print("E117=WRONG_MODEL_"+str(worker.get("model")),flush=True); raise SystemExit(32)
sel=worker.get("model_selection",{})
if sel.get("policy")!="SOL_EXACT" or sel.get("selected_slug")!="gpt-5.6-sol":
    print("E117=MODEL_SELECTION_MISMATCH",flush=True); raise SystemExit(33)
flags=worker.get("command_flags",[])
if "-m" not in flags or flags[flags.index("-m")+1]!="gpt-5.6-sol":
    print("E117=MODEL_COMMAND_MISMATCH",flush=True); raise SystemExit(34)

sha=lambda b: hashlib.sha256(b).hexdigest()
if task.get("input_sha256")!=sha(task.get("prompt","").encode()):
    print("E117=TASK_INPUT_HASH_MISMATCH",flush=True); raise SystemExit(35)
if complete.get("task_id")!=model_task or complete.get("input_sha256")!=task.get("input_sha256"):
    print("E117=COMPLETION_BINDING_MISMATCH",flush=True); raise SystemExit(36)
if any(e.get("item",{}).get("type") in {"command_execution","mcp_tool_call","web_search","file_change"} for e in events):
    print("E117=MODEL_TOOL_USE_FORBIDDEN",flush=True); raise SystemExit(37)

final=complete.get("final")
if not isinstance(final,str) or not final.strip():
    print("E117=FINAL_MISSING",flush=True); raise SystemExit(38)
try:
    result=json.loads(final)
except Exception:
    print("E117=FINAL_NOT_JSON",flush=True); raise SystemExit(39)

if result.get("candidate_id")!="AUTO-DISCOVERY-54d13314c7879b58e46d":
    print("E117=CANDIDATE_MISMATCH",flush=True); raise SystemExit(40)
files=result.get("files")
if not isinstance(files,dict) or len(files)!=3:
    print("E117=FILESET_INVALID",flush=True); raise SystemExit(41)

print("E117=R4_COMPLETE_EXACT_SOL files="+str(len(files))+" checkpoint="+str(env.get("checkpoint")),flush=True)
raise SystemExit(0)
